def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

print(factorial(5))   # 120

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

print(gcd(12, 18))   # 6

def lcm(a, b):
    return a * b // gcd(a, b)

print(lcm(4, 6))     # 12

def is_perfect(n):
    total = 0
    for i in range(1, n):
        if n % i == 0:
            total += i
    return total == n

print(is_perfect(6))    # True
print(is_perfect(28))   # True

def power(base, exp):
    result = 1
    for _ in range(exp):
        result *= base
    return result

print(power(2, 10))   # 1024

